def stats(a, b):
    """Sum and product, together."""
    return (a + b, a * b)


print(stats(2, 3))

def ends_doubled(values):
    """Double the first and last items, via one local helper."""
    def double(n):
        """Twice n."""
        return n * 2

    return (double(values[0]), double(values[-1]))


print(ends_doubled([1, 2, 7]))
